 reina:{name:'Reina Sofía',area:'Atocha',lat:40.408,lng:-3.6945,address:'Calle de Santa Isabel 52',wiki:W('Museo Nacional Centro de Arte Reina Sofía'),story:'The convenient Friday museum option from Pacífico. Keep the visit focused on Guernica and a little context rather than racing through every floor.',practical:'Friday free 19:00–21:00. Leave about 20:00 to reach Casa Paco around 21:00. This replaces the Retiro walk.',source:SOURCES.reina,tickets:'https://www.museoreinasofia.es/visita',kind:'museum'},
